{
  "references": [
    {
      "id": "R1",
      "summary_ko": "프롬프트에 물을 마시는 것에 대한 내용이 포함되어 있지 않음."
    },
    {
      "id": "R2",
      "summary_ko": "책상의 모니터들이 여성이 아닌 카메라를 향해 반대로 배치되어 있음."
    },
    {
      "id": "R3",
      "summary_ko": "모든 모니터가 여성을 등지고 카메라 방향을 향하고 있음."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "여성이 손을 움직일 때 오른손에 펜이 저절로 생겨남."
    },
    {
      "id": "C2",
      "summary_ko": "여성이 물을 마실 때 유리잔의 모양이 부자연스럽게 변형됨."
    },
    {
      "id": "C3",
      "summary_ko": "여성이 손을 뻗을 때 오른손에 펜이 갑자기 나타남."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "프롬프트 불일치(물 마시기)와 펜이 생성되는 현상은 대상과 결함 내용이 완전히 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 물을 마시는 행동 자체가 프롬프트에 없다는 지적이며, C2는 물잔의 형태 왜곡을 지적하므로 결함의 초점이 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "물 마시는 행동에 관한 언급과 펜이 나타나는 현상은 서로 다른 결함입니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "모니터의 방향 문제와 펜의 생성 현상은 대상과 결함이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "모니터의 배치 오류와 물잔의 형태 왜곡은 대상과 현상이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "모니터 방향 오류와 펜이 갑자기 나타나는 현상은 서로 무관합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "모니터가 카메라를 향해 반대로 놓인 결함과 펜의 생성 현상은 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "모니터 배치 오류와 물잔의 형태 변형은 서로 다른 결함입니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "모니터의 방향 문제와 펜이 출현하는 현상은 대상과 결함이 완전히 다릅니다."
    }
  ]
}
